  "tag_hints": [
    "high-voltage power supply",
    "detector bias",
    "PMT bias",
    "HV ramp control",
    "current trip protection",
    "multi-channel HV",
    "serial instrument control"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化并同步高压电源。",
      "description_en": "Initialize and synchronize the high-voltage power supply."
    },
    {
      "action_name": "auto-set_high_voltage",
      "description": "设置高压输出设定值。",
      "description_en": "Set the high-voltage output setpoint."
    },
    {
      "action_name": "auto-get_high_voltage",
      "description": "获取高压输出设定值。",
      "description_en": "Get the high-voltage output setpoint."
    },
    {
      "action_name": "auto-get_current",
      "description": "获取输出电流。",
      "description_en": "Get the output current."
    },
    {
      "action_name": "auto-get_voltage",
      "description": "获取输出电压。",
      "description_en": "Get the output voltage."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置输出电压。",
      "description_en": "Set the output voltage."
    },
    {
      "action_name": "auto-get_source_voltage",
      "description": "获取目标输出电压设定值。",
      "description_en": "Get the target output voltage setpoint."
    },
    {
      "action_name": "auto-get_hardware_voltage_limit",
      "description": "获取硬件电压限制。",
      "description_en": "Get the hardware voltage limit."
    },
    {
      "action_name": "auto-get_voltage_limit",
      "description": "获取软件电压限制。",
      "description_en": "Get the software voltage limit."
    },
    {
      "action_name": "auto-set_voltage_limit",
      "description": "设置软件电压限制。",
      "description_en": "Set the software voltage limit."
