      "action_name": "auto-get_current_limit",
      "description": "获取电流限制。",
      "description_en": "Get the current limit."
    },
    {
      "action_name": "auto-get_current_trip",
      "description": "获取过流跳闸阈值。",
      "description_en": "Get the current trip threshold."
    },
    {
      "action_name": "auto-set_current_trip",
      "description": "设置过流跳闸阈值。",
      "description_en": "Set the current trip threshold."
    },
    {
      "action_name": "auto-start_voltage_ramp",
      "description": "启动电压斜坡变化。",
      "description_en": "Start the voltage ramp."
    },
    {
      "action_name": "auto-get_current_channel",
      "description": "获取当前选定通道。",
      "description_en": "Get the currently selected channel."
    },
    {
      "action_name": "auto-set_current_channel",
      "description": "设置当前选定通道。",
      "description_en": "Set the currently selected channel."
    },
    {
      "action_name": "auto-get_identifier",
      "description": "获取模块标识信息。",
      "description_en": "Get the module identifier."
    },
    {
      "action_name": "auto-get_ramp_speed",
      "description": "获取电压斜坡速度。",
      "description_en": "Get the voltage ramp speed."
    },
    {
      "action_name": "auto-set_ramp_speed",
      "description": "设置电压斜坡速度。",
      "description_en": "Set the voltage ramp speed."
    },
    {
      "action_name": "auto-get_answer_delay",
      "description": "获取串口响应延时。",
      "description_en": "Get the serial response delay."
    },
    {
      "action_name": "auto-set_answer_delay",
      "description": "设置串口响应延时。",
      "description_en": "Set the serial response delay."
    },
    {
      "action_name": "auto-get_autostart",
      "description": "获取电压变更是否自动启动。",
      "description_en": "Get whether voltage changes start automatically."
    },
    {
      "action_name": "auto-set_autostart",
      "description": "设置电压变更是否自动启动。",
      "description_en": "Set whether voltage changes start automatically."
    },
    {
      "action_name": "auto-get_polarity",
