    {
      "action_name": "auto-write",
      "description": "向电源发送原始命令。",
      "description_en": "Send a raw command to the power supply."
    },
    {
      "action_name": "auto-query",
      "description": "向电源发送原始查询并读取回复。",
      "description_en": "Send a raw query to the power supply and read the reply."
    },
    {
      "action_name": "auto-on",
      "description": "开启高压输出。",
      "description_en": "Turn on the high-voltage output."
